def sim(g, drule, stoprule='edge', cheb=3, conflict=False):
    H,W=len(g),len(g[0])
    pts=[(r,c,g[r][c]) for r in range(H) for c in range(W) if g[r][c]]
    res=[row[:] for row in g]
    for r,c,v in pts:
        others=[p for p in pts if p!=(r,c)]
        if not others:
            # default: up
            d=(-1,0); breakcont=False
        else:
            if drule=='away_from_nearest_seed':
                best=min(others,key=lambda o:abs(o[0]-r)+abs(o[1]-c))
                d=(sign(r-best[0]),sign(c-best[1]))
            elif drule=='away_from_centroid':
                cs=sum(o[0] for o in others)/len(others); cc_=sum(o[1] for o in others)/len(others)
                d=(sign(r-cs),sign(c-cc_))
            elif drule=='toward_farthest_edge':
                best=None
                for dname,d in D.items():
                    rr,cc=r+d[0],c+d[1]
                    depth=0
                    while 0<=rr<H and 0<=cc<W: depth+=1; rr+=d[0]; cc+=d[1]
                    if best is None or depth>best[0]: best=(depth,d)
                d=best[1]
        sr,sc=r+d[0],c+d[1]
        p=[]
        while True:
            if not (0<=sr<H and 0<=sc<W): break
            if (sr==0 or sr==H-1 or sc==0 or sc==W-1): break
            if conflict:
                nb=[(sr+a,sc+b) for a,b in [(-1,0),(1,0),(0,-1),(0,1)] if any(p2==(sr+a,sc+b) for p2 in [(o[0],o[1]) for o in others])]
                if nb: break
            if stoprule=='cheb':
                for o in others:
                    ch=max(abs(sr-o[0]),abs(sc-o[1]))
                    if ch>=cheb: break
            p.append((sr,sc)); sr+=d[0]; sc+=d[1]
        for pr,pc in p: res[pr][pc]=5
        if p: res[p[-1][0]][p[-1][1]]=v
    return res
